" let h='<tr><th '+th+'>#</th><th '+th+'>Source</th><th '+th+'>SId</th><th '+th+'>Label</th><th '+th+'>kbit/s</th><th '+th+'>Prot.</th><th '+th+'>Slides</th><th '+th+'>CU</th><th '+th+'></th></tr>';\n"
" mux.svc.forEach((s,i)=>{const k=srcKind(s.src);\n"
"  h+='<tr><td style=\"white-space:nowrap;padding:6px 4px;border-top:1px solid var(--sep);vertical-align:top\"><span style=\"display:inline-block;width:10px;height:10px;border-radius:3px;background:'+SVCOL[i%8]+'\"></span>&nbsp;'+(i+1)+'</td>'\n"
"   +'<td '+td+'><select data-i=\"'+i+'\" data-k=\"kind\"><option value=\"i2s\"'+(k==='i2s'?' selected':'')+'>I2S input</option><option value=\"tone\"'+(k==='tone'?' selected':'')+'>Test tone</option><option value=\"zmq\"'+(k==='zmq'?' selected':'')+'>ZeroMQ</option></select>'\n"
"   +(k==='i2s'?'':'<br><input data-i=\"'+i+'\" data-k=\"arg\" type=\"number\" style=\"width:6.5em;margin-top:4px\" value=\"'+esc(srcArg(s.src))+'\" title=\"'+(k==='zmq'?'TCP port':'tone Hz')+'\"> <small style=\"color:var(--tx2)\">'+(k==='zmq'?'port':'Hz')+'</small>')+'</td>'\n"
"   +'<td '+td+'><input data-i=\"'+i+'\" data-k=\"sid\" type=\"text\" maxlength=\"4\" style=\"width:4.5em\" value=\"'+esc(s.sid)+'\"></td>'\n"
"   +'<td '+td+'><input data-i=\"'+i+'\" data-k=\"label\" type=\"text\" maxlength=\"16\" style=\"width:9.5em\" value=\"'+esc(s.label)+'\"></td>'\n"
"   +'<td '+td+'>'+(k==='zmq'?'<span title=\"Set by the sender (odr-audioenc -b); a change there is taken over automatically\" style=\"white-space:nowrap\">'+esc(s.br)+' <small style=\"color:var(--tx2)\">auto</small></span>':'<select data-i=\"'+i+'\" data-k=\"br\">'+brOpts(+s.br,s.prot)+'</select>')+'</td>'\n"
"   +'<td '+td+'><select data-i=\"'+i+'\" data-k=\"prot\">'+['1A','2A','3A','4A','1B','2B','3B','4B'].map(p=>'<option'+(p===s.prot?' selected':'')+(k==='zmq'&&p[1]==='B'&&s.br%32?' disabled':'')+'>'+p+'</option>').join('')+'</select></td>'\n"
"   +'<td '+td+'><input data-i=\"'+i+'\" data-k=\"sls\" type=\"checkbox\"'+(s.sls?' checked':'')+'></td>'\n"
"   +'<td '+td+' id=\"db_c'+i+'\"></td>'\n"
"   +'<td '+td+'><button class=\"go alt\" data-i=\"'+i+'\" data-k=\"del\" title=\"Remove this service\"'+(mux.svc.length<2?' disabled':'')+'>&times;</button></td></tr>'\n"
"   +'<tr><td></td><td colspan=\"8\" id=\"db_s'+i+'\" style=\"padding:0 4px 8px;font-size:13px\">'+stCell(i)+'</td></tr>';});\n"
" $('db_t').innerHTML=h;\n"
" $('db_t').querySelectorAll('[data-k]').forEach(el=>{const i=+el.dataset.i,k=el.dataset.k;\n"
"  const upd=()=>{const s=mux.svc[i];if(!s)return;\n"
"   if(k==='del'){mux.svc.splice(i,1);renderMux();muxChanged();return;}\n"
"   if(k==='kind'){const used=mux.svc.some((x,j)=>j!==i&&srcKind(x.src)!=='zmq');if(el.value!=='zmq'&&used){toast('Only one service can be encoded here');el.value=srcKind(s.src);return;}\n"
"    s.src=el.value==='zmq'?'zmq:'+nextPort():el.value==='tone'?'tone:1000':'i2s';renderMux();muxChanged();return;}\n"
"   if(k==='arg'){s.src=srcKind(s.src)+':'+el.value;}\n"
"   else if(k==='sid')s.sid=el.value.toUpperCase();else if(k==='label')s.label=el.value;else if(k==='sls')s.sls=el.checked;\n"
"   else if(k==='br')s.br=el.value;else if(k==='prot'){s.prot=el.value;if(s.prot[1]==='B'&&s.br%32){s.br=String(Math.max(32,Math.round(s.br/32)*32));}renderMux();}\n"
"   muxChanged();};\n"
"  el.onchange=upd;if(el.tagName==='INPUT'&&el.type==='text')el.oninput=upd;});\n"
" drawCU();$('db_undo').disabled=!muxDirty;}\n"
"function nextPort(){const used=mux.svc.filter(s=>srcKind(s.src)==='zmq').map(s=>+srcArg(s.src));let p=2491;while(used.includes(p))p++;return p;}\n"
"function nextSid(){const used=mux.svc.map(s=>parseInt(s.sid,16));let v=0x8F01;while(used.includes(v))v++;return v.toString(16).toUpperCase();}\n"
"$('db_add').onclick=()=>{if(!mux)return;if(mux.svc.length>=8){toast('At most 8 services');return;}mux.svc.push({src:'zmq:'+nextPort(),sid:nextSid(),label:'Service '+(mux.svc.length+1),br:'128',prot:'3A',sls:true});renderMux();muxChanged();};\n"
"$('db_lab').oninput=()=>{if(mux){mux.label=$('db_lab').value;muxChanged();}};\n"
"$('db_eid').oninput=()=>{if(mux){mux.eid=$('db_eid').value.toUpperCase();muxChanged();}};\n"
"$('db_undo').onclick=()=>{mux=parseMux(muxOrig);muxDirty=false;renderMux();$('db_msg').textContent='';};\n"
"$('db_apply').onclick=async()=>{if(!mux)return;$('db_apply').disabled=true;try{const r=await api('/api/mux',{method:'POST',headers:{'X-Requested-With':'skypluto','Content-Type':'text/plain'},body:fmtMux(mux)});const t=(await r.text()).trim();\n"
" const ok=t.startsWith('OK');$('db_msg').innerHTML='<span style=\"color:'+(ok?'var(--ok)':'var(--bad)')+'\">'+esc(t)+'</span>';if(ok){muxOrig=fmtMux(mux);muxDirty=false;drawCU();$('db_undo').disabled=true;}toast(ok?'Multiplex stored':t);}catch(e){toast('No connection');}$('db_apply').disabled=false;};\n"
"async function pollMux(first){if(authNeeded||((tab!=='ct'||$('t-db').hidden)&&!first))return;try{const j=await (await api('/api/mux')).json();$('dbno').style.display=j.has?'none':'block';\n"
" const d=kv(j.dab||'');muxStat=d;const t=(j.mux||'');\n"
" if(!muxDirty&&t!==muxOrig){muxOrig=t;mux=parseMux(t);renderMux();}\n"
" if(mux)mux.svc.forEach((s,i)=>{const e=$('db_s'+i);if(e)e.innerHTML=stCell(i);});\n"
" slsRender();\n"
" $('db_air').textContent=d.m==='DAB'?('DAB on the air · '+(d.svc||'?')+' services · '+(d.cu||'?')+' CU'+(d.chg?' · reconfiguration at CIF '+d.chg:'')+(d.run==='1'?'':' · program not running')):'FM (DAB is off: the layout takes effect with M DAB)';\n"
"}catch(e){}}\n"
"// ---- slideshow of the service encoded here (inside the multiplex panel) -------------------------------------------------------\n"
"let sls=null,slsBusy=false;\n"
"function slsLocal(){return mux?mux.svc.findIndex(s=>srcKind(s.src)!=='zmq'):-1;}\n"
"function slsRate(){const i=slsLocal();const kb=i<0?0:+mux.svc[i].br;return (kb>=128?48:kb>=80?32:kb>=48?24:8)*50;}   // PAD bytes per second for the slideshow (skypluto-dab)\n"
"function slsRender(){if(!sls)return;const li=slsLocal(),on=li>=0&&mux.svc[li].sls,st=(muxStat.sls||'').split('/'),cnt=sls.size.filter(x=>x>0).length,tot=sls.size.reduce((a,b)=>a+b,0),rate=slsRate();\n"
" $('sl_st').innerHTML=li<0?'<span style=\"color:var(--warn)\">No service is encoded here (I2S input or test tone): a slideshow needs one.</span>'\n"
"  :!on?'<span style=\"color:var(--warn)\">Off: the service encoded here ('+esc(mux.svc[li].label)+') does not announce a slideshow.</span> <button class=\"go alt\" id=\"sl_on\" style=\"margin-left:6px\">Switch on</button>'\n"
"  :!cnt?'On, but there are no slides yet.':(muxStat.m==='DAB'&&st.length===3?'On the air: '+st[0]+' slide'+(st[0]==='1'?'':'s')+(+st[1]?' · slide '+st[1]+(st[2]==='1'?' being sent':' shown'):''):'On ('+cnt+' slide'+(cnt===1?'':'s')+'); DAB is not on the air.');\n"
" const b=$('sl_on');if(b)b.onclick=()=>{if(muxDirty){toast('Apply or undo the multiplex changes first');return;}mux.svc[li].sls=true;renderMux();muxChanged();$('db_apply').click();};\n"
" let h='';sls.size.forEach((s,i)=>{if(!s)return;const cur=st.length===3&&+st[1]===i+1;\n"
"  h+='<div style=\"position:relative;width:160px\"><img src=\"/api/sls/'+(i+1)+'?v='+s+'\" alt=\"slide '+(i+1)+'\" style=\"width:160px;height:120px;object-fit:contain;background:#000;border-radius:8px;display:block'+(cur?';outline:2px solid var(--ac)':'')+'\">'\n"
"   +'<div class=\"sub\" style=\"margin-top:3px;font-size:12px\">'+(i+1)+' · '+(s/1024).toFixed(1)+' kB · ~'+Math.ceil((s+200)/rate)+' s</div>'\n"
"   +'<button class=\"go alt\" data-sl=\"'+(i+1)+'\" title=\"Remove this slide\" style=\"position:absolute;top:4px;right:4px;padding:2px 8px\">&times;</button></div>';});\n"
" $('sl_grid').innerHTML=h||'<span class=\"sub\">No slides.</span>';\n"
" document.querySelectorAll('#sl_grid button[data-sl]').forEach(b=>b.onclick=async()=>{const r=await (await api('/api/sls/'+b.dataset.sl+'/del',{method:'POST',headers:{'X-Requested-With':'skypluto'}})).text();if(!r.startsWith('OK'))toast(r);slsLoad();});\n"
" if(document.activeElement!==$('sl_int'))$('sl_int').value=sls.int;\n"
" $('sl_use').textContent=(tot/1024).toFixed(0)+' of '+(sls.all/1024).toFixed(0)+' kB used · '+(sls.free/1024).toFixed(0)+' kB free in the flash · a full round takes about '+Math.max(cnt*sls.int,Math.ceil(tot/rate))+' s';\n"
" $('sl_add').disabled=slsBusy||cnt>=8;}\n"
"async function slsLoad(){try{sls=await (await api('/api/sls')).json();slsRender();}catch(e){}}\n"
"// scale into 320 x 240 (contain, black bars) and compress to JPEG of at most ~30 kB\n"
"function slsPrep(file){return new Promise((ok,bad)=>{const u=URL.createObjectURL(file),im=new Image();im.onerror=()=>{URL.revokeObjectURL(u);bad(new Error('not an image'));};\n"
" im.onload=()=>{URL.revokeObjectURL(u);const c=document.createElement('canvas');c.width=320;c.height=240;const g=c.getContext('2d');g.fillStyle='#000';g.fillRect(0,0,320,240);\n"
"  const k=Math.min(320/im.naturalWidth,240/im.naturalHeight),w=im.naturalWidth*k,h=im.naturalHeight*k;g.imageSmoothingQuality='high';g.drawImage(im,(320-w)/2,(240-h)/2,w,h);\n"
"  const tryq=q=>c.toBlob(b=>{if(!b){bad(new Error('could not be converted'));return;}if(b.size>30*1024&&q>0.35)tryq(q-0.1);else ok(b);},'image/jpeg',q);tryq(0.85);};\n"
" im.src=u;});}\n"
"$('sl_add').onclick=()=>$('sl_file').click();\n"
"$('sl_file').onchange=async()=>{const files=[...$('sl_file').files];$('sl_file').value='';if(!files.length||!sls)return;slsBusy=true;slsRender();\n"
" for(const f of files){const n=sls.size.findIndex(s=>!s)+1;if(!n){toast('At most 8 slides');break;}\n"
"  try{const b=await slsPrep(f);const r=(await (await api('/api/sls/'+n,{method:'POST',headers:{'X-Requested-With':'skypluto','Content-Type':'image/jpeg'},body:b})).text()).trim();\n"
"   if(!r.startsWith('OK')){toast(f.name+': '+r);break;}sls.size[n-1]=b.size;toast(f.name+' → slide '+n+' ('+(b.size/1024).toFixed(1)+' kB)');}\n"
"  catch(e){toast(f.name+': '+(e.message||'upload failed'));break;}}\n"
" slsBusy=false;slsLoad();};\n"
"$('sl_setint').onclick=async()=>{const r=(await (await api('/api/sls/int',{method:'POST',headers:{'X-Requested-With':'skypluto','Content-Type':'text/plain'},body:String(+$('sl_int').value)})).text()).trim();toast(r.startsWith('OK')?'Interval '+$('sl_int').value+' s':r);slsLoad();};\n"
"const muxShow=v=>{$('t-db').hidden=!v;$('b_mux').textContent=v?'Hide multiplex settings':'Multiplex settings';if(v){pollMux(true);slsLoad();$('t-db').scrollIntoView({behavior:'smooth',block:'start'});}};\n"
"$('b_mux').onclick=()=>muxShow($('t-db').hidden);$('b_muxc').onclick=()=>{muxShow(false);$('b_mux').scrollIntoView({block:'center'});};\n"
"setInterval(pollMux,2000);pollMux(true);\n"
"setInterval(poll,1000);setInterval(pollMask,1000);setInterval(pollG,250);setInterval(pollTone,400);poll();pollMask();\n"
"document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});\n"
"</script></body></html>\n"
"\n";
static const unsigned WEB_INDEX_LEN = sizeof(WEB_INDEX) - 1;
